reproduction_artifacts.request_probe_source:
#define _POSIX_C_SOURCE 200809L
#include <stdlib.h>
#include <stdio.h>
#include <assert.h>
static size_t calls, fail_at, live;
static int persistent;
static void *fm(size_t n) { calls++; if(fail_at && (calls==fail_at || (persistent && calls>=fail_at))) return NULL; void *p=malloc(n); if(p) live++; return p; }
static void ff(void *p) { if(p) { assert(live); live--; free(p); } }
#define free ff
#include "/src/core/src/context/interpreter.c"
#undef free
int main(void) {
 rc_interpreter_input in={.revision=1,.evidence_count=1}; strcpy(in.evidence[0].id,"e1"); strcpy(in.evidence[0].source,"executor"); strcpy(in.evidence[0].text,"fixture");
 rc_interpreter w={.tokens=4096,.structured_output=true}; strcpy(w.model,"fixture");
 json_set_alloc_funcs(fm,ff);
 char *body=request_body(&w,&in); assert(body); char *expected=strdup(body); assert(expected); size_t total=calls; ff(body); assert(!live);
 for(persistent=0;persistent<=1;persistent++) for(size_t i=1;i<=total;i++) {
   calls=0; fail_at=i; body=request_body(&w,&in);
   if(body) { fprintf(stderr,"success allocation=%zu mode=%d equal=%d\nEXPECTED=%s\nACTUAL=%s\n",i,persistent,!strcmp(body,expected),expected,body); ff(body); }
   if(live) { fprintf(stderr,"LEAK allocation=%zu mode=%d live=%zu\n",i,persistent,live); return 1; }
 }
 fprintf(stderr,"request fault injection: %zu allocation sites x 2 failure modes; zero live allocations\n",total); free(expected); return 0;
}
